import { OFFICE, UNIVERSITY } from "./characters";

/**
 * Pixel art, authored as character grids.
 *
 * One char = one pixel. "." is transparent. Keys map to PALETTE below, and
 * every entry is a CSS custom property rather than a hex value so the entire
 * pixel world recolours when the day/night theme flips.
 *
 * Large sprites live in characters.ts and are generated by
 * scripts/build-sprites.py, which proves each row's width.
 */

const V = (name: string) => `var(--px-${name})`;

export const PALETTE: Record<string, string> = {
  k: V("ink"), // outline
  d: V("cloth-dark"),
  a: V("accent"),
  g: V("glow"),
  p: V("stone"), // pipe body
  t: V("stone"),
  w: V("win-near"),
  c: V("win-mid"),
  G: V("class-primary"), // generic green
  W: V("stone-light"),
};

/** CRT terminal on a stand. 14 x 11. */
export const TERMINAL = [
  "kkkkkkkkkkkkkk",
  "kddddddddddddk",
  "kd.GG.......dk",
  "kd..........dk",
  "kd.aaaaa....dk",
  "kd..........dk",
  "kd.GG.......dk",
  "kddddddddddddk",
  "kkkkkkkkkkkkkk",
  "....kkkkkk....",
  "..kkkkkkkkkk..",
];

/** A length of pipe with data moving through it. 16 x 5. */
export const PIPE = [
  "................",
  "kkkkkkkkkkkkkkkk",
  "pGGppGGppGGppGGp",
  "kkkkkkkkkkkkkkkk",
  "................",
];

export const SPRITES = {
  university: UNIVERSITY,
  office: OFFICE,
  terminal: TERMINAL,
  pipe: PIPE,
} as const;

export type SpriteName = keyof typeof SPRITES;
